package manifest

import (
	"strings"
	"testing"
)

// TestCargoLockReadsPins proves each [[package]] table contributes a pin,
// a lower version is not a raise, and a dependency array is not a pin.
func TestCargoLockReadsPins(t *testing.T) {
	base := []byte(strings.Join([]string{
		"version = 3",
		"",
		"[[package]]",
		"name = \"app\"",
		"version = \"0.1.0\"",
		"",
		"[[package]]",
		"name = \"regex\"",
		"version = \"1.5.0\"",
		"dependencies = [",
		" \"aho-corasick\",",
		"]",
		"",
	}, "\n"))
	change := []byte(strings.Join([]string{
		"# This file is automatically @generated by Cargo.",
		"version = 3",
		"",
		"[[package]]",
		"name = \"app\"",
		"version = \"0.1.0\"",
		"",
		"[[package]]",
		"name = \"libc\"",
		"version = \"0.2.140\"",
		"",
		"[[package]]",
		"name = \"regex\"",
		"version = \"1.9.1\"",
		"",
	}, "\n"))
	got, err := diffCargoLock(base, change)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 2 {
		t.Fatalf("%#v", got)
	}
	if got[0].Package != "libc" || got[0].Version != "0.2.140" || !got[0].Added || got[0].Line != 10 {
		t.Fatalf("%#v", got[0])
	}
	if got[1].Package != "regex" || got[1].Version != "1.9.1" || got[1].Added || got[1].Line != 14 {
		t.Fatalf("%#v", got[1])
	}
}

// TestCargoLockRejectsAFileWithNoPackage proves a lock file that is not a
// package list returns an error, so Collect can record it as a note, and
// names the side that failed.
func TestCargoLockRejectsAFileWithNoPackage(t *testing.T) {
	if _, err := diffCargoLock([]byte("version = 3\n"), []byte("[[package]]\nname = \"regex\"\nversion = \"1.0.0\"\n")); err == nil || !strings.Contains(err.Error(), "base:") {
		t.Fatal(err)
	}
	if _, err := diffCargoLock([]byte("this is not a lock\n"), []byte("")); err == nil || !strings.Contains(err.Error(), "base:") {
		t.Fatal(err)
	}
}

// TestCargoLockMatch proves the reader matches Cargo.lock at any depth and
// not the manifest or a backup.
func TestCargoLockMatch(t *testing.T) {
	r := CargoLock()
	if r.Ecosystem != "crates.io" || !r.Lock || !r.NoteErr || r.Compare == nil || r.Explain == nil {
		t.Fatal(r.Ecosystem)
	}
	if !r.Match("Cargo.lock") || !r.Match("app/Cargo.lock") {
		t.Fatal("missed Cargo.lock")
	}
	if r.Match("Cargo.toml") || r.Match("Cargo.lock.bak") || r.Match("not-Cargo.lock") || r.Match("cargo.lock") {
		t.Fatal("matched a file that is not Cargo.lock")
	}
}
